#!/usr/bin/env bash
# wake-pi.sh — start a headless pi turn for one handoff.
# Generated by `install.sh --target pi`.
#
#   wake-pi.sh "<handoff>"            # a fresh headless turn
#   wake-pi.sh "<handoff>" <sid>      # resume session <sid>
#
# A worker must run in the card's project directory, and only this host-local
# glue can resolve it. Inputs (set by the supervisor):
#   TP_PROJECT        the card's board project identity
#   TP_PROJECTS_JSON  the local project map (default: beside the installed skill)
#   TP_NODE           node used to resolve it (default: `node` on PATH)
# If the directory cannot be resolved, exit 3 without starting a worker. If your
# pi build differs, point the supervisor's `--wake-command` at your own glue.
set -eu

prompt="${1:-}"
sid="${2:-}"

if [ -z "$prompt" ]; then
  echo "wake-pi: a handoff prompt is required" >&2
  exit 2
fi

projects_json="${TP_PROJECTS_JSON:-$(dirname "$0")/../skills/meerkat-taskpanel/projects.json}"
if ! cwd="$("${TP_NODE:-node}" "{{LOOP}}/scripts/wake-cwd.mjs" --project "${TP_PROJECT:-}" --projects-json "$projects_json")"; then
  echo "wake-pi: refusing to wake a worker without a target directory" >&2
  exit 3
fi
# `if !` cannot catch an empty $cwd: `cd ""` succeeds in bash and would run the
# worker in the caller's directory. The absolute-path test covers empty and relative.
case "$cwd" in
  /*) ;;
  *) echo "wake-pi: refusing to wake a worker without a target directory" >&2; exit 3 ;;
esac
cd "$cwd"
echo "wake-pi: working directory $cwd" >&2

# Full tool access is the documented opt-in, recorded in the host config beside
# this script (never a default). The reason is printed so the bypass is visible.
allow_all="$(sed -n 's/^MEERKAT_TASKPANEL_ALLOW_ALL_TOOLS=//p' "$(dirname "$0")/../meerkat-taskpanel.env" 2>/dev/null | tail -1)"
allow_reason="$(sed -n 's/^MEERKAT_TASKPANEL_ALLOW_ALL_TOOLS_REASON=//p' "$(dirname "$0")/../meerkat-taskpanel.env" 2>/dev/null | tail -1)"
allow_flag=""
case "$allow_all" in
  yes | YES | true | 1)
    allow_flag="1"
    echo "wake-pi: full tool access enabled (authorized by: ${allow_reason:-unrecorded})" >&2
    ;;
esac

if [ -n "$sid" ]; then
  exec pi ${allow_flag:+--approve} --print --session "$sid" "$prompt"
fi

exec pi ${allow_flag:+--approve} --print "$prompt"
